/* FX (ink doodles; follow the paper colour via currentColor) */
const sp = (x, y, s = 1, dl = 0, fill = 'currentColor', d = '1.8s') => `<path d="${sparkD(x, y, s)}" fill="${fill}" ${A('a-twinkle', x, y, `--dl:${dl}s;--d:${d}`)}/>`;
const st5 = (x, y, r = 7, dl = 0, fill = 'currentColor', d = '1.8s') => `<path d="${star5(x, y, r)}" fill="${fill}" ${A('a-twinkle', x, y, `--dl:${dl}s;--d:${d}`)}/>`;
const zzz = (x, y) => [0, 1, 2].map(i => `<text x="${x}" y="${y}" font-family="Bricolage Grotesque, system-ui" font-weight="800" font-size="${14 + i * 5}" fill="currentColor" ${A('a-float', x, y, `--dl:${i * .9}s;--d:2.7s;--fx-x:${10 + i * 4}px`)}>z</text>`).join('');
const dots = (x, y) => [0, 1, 2].map(i => `<circle cx="${x + i * 12}" cy="${y}" r="4.2" fill="currentColor" ${A('a-dot', x + i * 12, y, `--dl:${i * .2}s`)}/>`).join('');
const bang = (x, y) => `<g ${A('a-pop', x + 8, y + 30, '--d:2.2s')} fill="currentColor"><path d="M${x} ${y} L${x + 7} ${y} L${x + 5} ${y + 22} L${x + 2} ${y + 22} Z"/><circle cx="${x + 3.5}" cy="${y + 29}" r="3.6"/><path d="M${x + 13} ${y + 2} L${x + 20} ${y + 2} L${x + 18} ${y + 24} L${x + 15} ${y + 24} Z"/><circle cx="${x + 16.5}" cy="${y + 31}" r="3.6"/></g>`;
const note = (x, y) => `<ellipse cx="${x}" cy="${y}" rx="5" ry="4" transform="rotate(-20 ${x} ${y})" fill="currentColor"/><path d="M${x + 4} ${y - 1} L${x + 4} ${y - 18} Q${x + 10} ${y - 15} ${x + 12} ${y - 9}" stroke="currentColor" stroke-width="2.4" fill="none" stroke-linecap="round"/>`;
const notes = (x, y) => [0, 1, 2].map(i => `<g ${A('a-float', x, y, `--dl:${i * .8}s;--d:2.4s;--fx-x:${i % 2 ? -6 : 10}px`)}>${note(x + i * 8, y)}</g>`).join('');
const heartsUp = (x, y) => [0, 1, 2].map(i => `<path d="${heartD(x + i * 10, y, 1.1 + i * .2)}" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linejoin="round" ${A('a-float', x, y, `--dl:${i * .7}s;--d:2.2s`)}/>`).join('');
const burst = (cx, cy, n = 12) => Array.from({ length: n }, (_, i) => {
  const a = -Math.PI / 2 + ((i - (n - 1) / 2) / (n - 1)) * Math.PI * 1.35, dist = 58 + (i % 3) * 16;
  const dx = (Math.cos(a) * dist).toFixed(0), dy = (Math.sin(a) * dist * .8 + 26).toFixed(0);
  const k = i % 3, fill = i % 2 ? 'currentColor' : SOFT;
  const d = k === 0 ? star5(cx, cy, 6) : k === 1 ? sparkD(cx, cy, .7) : `M${cx - 3} ${cy - 3} h6 v6 h-6 Z`;
  return `<path d="${d}" fill="${fill}" ${A('a-burst', cx, cy, `--dx:${dx}px;--dy:${dy}px;--dl:${(i % 4) * .08}s`)}/>`;
}).join('');
const speed = (x, y, n = 3) => Array.from({ length: n }, (_, i) => `<path d="M${x} ${y + i * 12} l20 0" stroke="currentColor" stroke-width="3" stroke-linecap="round" ${A('a-speed', x, y, `--dl:${i * .18}s`)}/>`).join('');
const ringLines = (x, y) => `<g ${A('a-flash', x, y, '--d:.4s')} stroke="currentColor" stroke-width="2.6" fill="none" stroke-linecap="round"><path d="M${x - 34} ${y - 10} q-6 10 0 20"/><path d="M${x - 42} ${y - 14} q-8 14 0 28"/><path d="M${x + 34} ${y - 10} q6 10 0 20"/><path d="M${x + 42} ${y - 14} q8 14 0 28"/></g>`;
const scratch = (x, y) => [0, 1, 2].map(i => `<path d="M${x + i * 8} ${y} q3 6 0 12 q-3 6 0 12" stroke="currentColor" stroke-width="2.6" fill="none" stroke-linecap="round" ${A('a-flash', x, y, `--d:1.2s;--dl:${i * .15}s`)}/>`).join('');
const anger = (x, y) => `<g ${A('a-pulse', x, y, '--d:.6s')} stroke="currentColor" stroke-width="3" fill="none" stroke-linecap="round"><path d="M${x - 10} ${y - 3} q4 0 4 -7"/><path d="M${x + 3} ${y - 10} q0 4 7 4"/><path d="M${x + 10} ${y + 3} q-4 0 -4 7"/><path d="M${x - 3} ${y + 10} q0 -4 -7 -4"/></g>`;
const bubbles = (x, y) => [0, 1, 2].map(i => `<circle cx="${x + (i - 1) * 9}" cy="${y}" r="${3 + i}" fill="none" stroke="currentColor" stroke-width="2" ${A('a-bubble', x, y, `--dl:${i * .7}s`)}/>`).join('');
const waveLines = (x, y) => `<g stroke="currentColor" stroke-width="2.6" stroke-linecap="round">${[0, 1, 2].map(i => `<path d="M${x + i * 9} ${y - (i === 1 ? 4 : 0)} l0 -12" ${A('a-flash', x, y, `--d:1.3s;--dl:${i * .12}s`)}/>`).join('')}</g>`;
const orbit = (cx, cy) => `<g transform="translate(${cx} ${cy}) scale(1 .38)"><g ${A('a-spin', 0, 0, '--d:2.2s')}>${[[50, 0], [-25, 43], [-25, -43]].map(([x, y]) => `<path d="${star5(x, y, 9)}" fill="currentColor"/>`).join('')}</g></g>`;

const wrapSvg = (main, fx = '', o = {}) => `<svg viewBox="0 0 200 200" role="img" aria-hidden="true">${o.defs ? `<defs>${o.defs}</defs>` : ''}<g filter="url(#se-${o.filter || 'ink'})">${main}</g><g>${fx}</g></svg>`;
const shift = (x, y, s, inner) => `<g ${T(x, y, s)}>${inner}</g>`;


/* ═════════ Kit 2 — extra motion, props and poses for stickers #56+ ═════════ */


/* Shared defs for new stickers (clip paths, extra filters) live in one hidden SVG. */

const defOnce = (_m) => ''; // clip paths live in <StickerDefs/>

/* Primitives */

const FONT = 'font-family="Bricolage Grotesque, system-ui" font-weight="800"';
const G = (cls, ox, oy, inner, vars = '') => `<g ${A(cls, ox, oy, vars)}>${inner}</g>`;
const at = (x, y, s, inner, r = 0) => `<g ${T(x, y, s, r)}>${inner}</g>`;
